export function celsiusToFahrenheit(celsius) {
    return celsius * 1.8 + 32;
}
export function feetToMeters(feet) {
    return feet * 0.3048;
}
export function milesToMeters(miles) {
    return miles * 1609.344;
}
export function metersToMiles(meters) {
    return meters / 1609.344;
}
export function inhgToKpa(inHg) {
    return inHg / 0.29529988;
}
export function kpaToInhg(kpa) {
    return kpa * 0.29529988;
}
export function kphToMps(kph) {
    return (kph / 3600) * 1000;
}
export function mpsToKts(mps) {
    return mps * 1.9438445;
}
export function ktsToMps(kts) {
    return kts / 1.9438445;
}
